const tone = $input.first().json['Tone'] || 'Professional';
const topic = $input.first().json['Topic'];
const audience = $input.first().json['Target Audience'] || 'professionals';
const keyPoints = $input.first().json['Key Points (optional)'] || '';
const includeHashtags = $input.first().json['Include Hashtags'] === 'Yes';
const includeCTA = $input.first().json['Include Call to Action'] === 'Yes';

let systemPrompt = `You are an expert LinkedIn content creator. You write posts that get high engagement — clear, punchy, and human. You understand LinkedIn's algorithm favors posts with strong hooks, line breaks for readability, and authentic voice.`;

let userPrompt = `Write a LinkedIn post about the following topic.

Topic: ${topic}
Tone: ${tone}
Target Audience: ${audience}`;

if (keyPoints) {
  userPrompt += `\nKey Points to Include:\n${keyPoints}`;
}

userPrompt += `\n\nFormatting rules:
- Start with a scroll-stopping hook (first line must grab attention)
- Use short paragraphs (1-3 sentences max)
- Add line breaks between paragraphs for readability
- Keep total length between 150-300 words
- Write in first person`;

if (includeHashtags) {
  userPrompt += `\n- End with 3-5 relevant hashtags`;
} else {
  userPrompt += `\n- Do NOT include any hashtags`;
}

if (includeCTA) {
  userPrompt += `\n- End with a clear, natural call to action (e.g. asking readers a question or to share their thoughts)`;
} else {
  userPrompt += `\n- Do NOT include a call to action`;
}

userPrompt += `\n\nOutput only the post text — no preamble, no explanations.`;

return [{
  json: {
    systemPrompt,
    userPrompt,
    topic,
    tone,
    audience
  }
}];

const rawContent = $input.first().json.content;

// Extract text from Anthropic response
let postText = '';
if (Array.isArray(rawContent)) {
  postText = rawContent
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('')
    .trim();
} else if (typeof rawContent === 'string') {
  postText = rawContent.trim();
}

// Count characters (LinkedIn limit: 3000)
const charCount = postText.length;
const withinLimit = charCount <= 3000;

if (!withinLimit) {
  // Trim to 3000 chars at last sentence boundary
  const trimmed = postText.substring(0, 2990);
  const lastPeriod = trimmed.lastIndexOf('.');
  postText = lastPeriod > 0 ? trimmed.substring(0, lastPeriod + 1) : trimmed;
}

return [{
  json: {
    postText,
    charCount: postText.length,
    topic: $('Build Prompt').first().json.topic,
    tone: $('Build Prompt').first().json.tone
  }
}];

const postText = $('Format & Validate Post').first().json.postText;
const topic = $('Format & Validate Post').first().json.topic;
const tone = $('Format & Validate Post').first().json.tone;
const charCount = $('Format & Validate Post').first().json.charCount;
const linkedInResponse = $input.first().json;

const postId = linkedInResponse.id || 'unknown';
const timestamp = new Date().toISOString();

return [{
  json: {
    success: true,
    postId,
    timestamp,
    topic,
    tone,
    charCount,
    postText,
    linkedInUrl: postId !== 'unknown' ? `https://www.linkedin.com/feed/update/${postId}/` : null
  }
}];
